using Microsoft.EntityFrameworkCore;using ProMaxx2.QA.Application.Execution;using ProMaxx2.QA.Domain.Execution;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class ExecutionRepository(QaDbContext db):IExecutionRepository
{
 public async Task<ExecutionWorkspaceDto?>WorkspaceAsync(Guid cycleId,CancellationToken ct)=>await db.TestCycles.AsNoTracking().Where(x=>x.TestCycleId==cycleId).Select(x=>new ExecutionWorkspaceDto(x.TestCycleId,x.CycleCode,x.CycleName,x.Status,db.Builds.Where(b=>b.BuildId==x.BuildId).Select(b=>b.BuildNumber).First(),db.TestEnvironments.Where(e=>e.TestEnvironmentId==x.EnvironmentId).Select(e=>e.EnvironmentName).First(),x.Cases.OrderBy(c=>c.ExecutionOrder).Select(c=>new CycleCaseExecutionDto(c.TestCycleCaseId,c.TestCaseId,c.TestCase.TestCaseCode,c.TestCase.Title,c.TestCase.Preconditions,c.Priority??c.TestCase.Priority,c.CurrentStatus,c.ExecutionOrder,c.TestCase.Steps.Where(s=>s.RevisionNo==c.TestCaseRevisionNo).OrderBy(s=>s.StepNo).Select(s=>new ExecutionStepDto(s.StepNo,s.Action,s.TestDataText,s.ExpectedResult)).ToList(),c.Executions.OrderByDescending(e=>e.ExecutionNo).Select(e=>new ExecutionHistoryDto(e.TestExecutionId,e.ExecutionNo,e.Status,e.ActualResult,e.Comment,db.Users.Where(u=>u.UserId==e.TesterUserId).Select(u=>u.DisplayName).First(),e.CompletedAt)).ToList())).ToList())).SingleOrDefaultAsync(ct);
 public Task<TestCycleCase?>FindCycleCaseAsync(Guid id,CancellationToken ct)=>db.TestCycleCases.Include(x=>x.Cycle).SingleOrDefaultAsync(x=>x.TestCycleCaseId==id,ct);public async Task<int>NextExecutionNoAsync(Guid id,CancellationToken ct)=>(await db.TestExecutions.Where(x=>x.TestCycleCaseId==id).Select(x=>(int?)x.ExecutionNo).MaxAsync(ct)??0)+1;public Task AddAsync(TestExecution e,CancellationToken ct)=>db.TestExecutions.AddAsync(e,ct).AsTask();public Task SaveAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
}
